PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS app_settings (id INTEGER PRIMARY KEY CHECK(id = 1), revision INTEGER NOT NULL CHECK(revision > 0), freshness_threshold_seconds INTEGER NOT NULL CHECK(freshness_threshold_seconds > 0), history_retention_days INTEGER NOT NULL CHECK(history_retention_days > 0), updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS provider_config (provider_id TEXT PRIMARY KEY CHECK(provider_id IN ('codex','claude','antigravity')), enabled INTEGER NOT NULL DEFAULT 0 CHECK(enabled IN (0,1)), verification TEXT NOT NULL DEFAULT 'unverified' CHECK(verification IN ('unverified','verified','unsupported')), verification_note TEXT, source_type TEXT, ownership_generation INTEGER NOT NULL DEFAULT 1 CHECK(ownership_generation > 0), updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS admin_sessions (handle_hash TEXT PRIMARY KEY, expires_at INTEGER NOT NULL, revoked_at INTEGER, created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS admin_sessions_expiry_idx ON admin_sessions(expires_at);
CREATE TABLE IF NOT EXISTS rate_limits (scope TEXT NOT NULL, subject_hash TEXT NOT NULL, window_start INTEGER NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, blocked_until INTEGER, expires_at INTEGER NOT NULL, PRIMARY KEY(scope, subject_hash, window_start));
CREATE INDEX IF NOT EXISTS rate_limits_expiry_idx ON rate_limits(expires_at);
INSERT OR IGNORE INTO app_settings(id, revision, freshness_threshold_seconds, history_retention_days, updated_at) VALUES (1,1,900,7,CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER));
